/**
 * Centralised, locale-aware SEO for a page.
 *
 * It reads the page copy from the active locale dictionary
 * (`<section>.metaTitle`, `.metaDescription`, `.keywords`, `.ogTitle`,
 * `.ogDescription`) and merges it with the framework-native technical SEO
 * generated by `@nuxtjs/i18n`:
 *   - `<html lang>` / `dir`            → rendered once in `app.vue`
 *   - self-referencing canonical       → `useLocaleHead({ seo: true })`
 *   - reciprocal hreflang alternates   → `useLocaleHead({ seo: true })`
 *   - `og:url` / `og:locale`           → derived from the locale + canonical
 *
 * Canonical + hreflang are injected by a single `useLocaleHead` call here so
 * they are never duplicated across pages.
 */
export interface LocalizedSeoOptions {
  /** `og:type` for this page (default `website`). */
  ogType?: string
  /** OG/Twitter image, absolute or site-relative (default `/og-image.jpg`). */
  image?: string
  /** Optional JSON-LD builder — receives the absolute self-canonical URL + locale. */
  schema?: (ctx: {
    url: string
    locale: string
  }) => Record<string, unknown> | Record<string, unknown>[]
}

/** Single source of truth for the canonical origin (matches `site.url`). */
const SITE_URL = 'https://matinjahi.netlify.app'

/** Open Graph locale codes (`language_TERRITORY`) per app locale. */
const OG_LOCALES: Record<string, string> = {
  en: 'en_US',
  fa: 'fa_IR',
}

export function useLocalizedSeo(
  section: string,
  options: LocalizedSeoOptions = {},
) {
  const { t, te, locale } = useI18n()

  // Technical SEO from i18n: reciprocal hreflang alternates + self canonical.
  // `dir`/`lang` are handled once, globally, in app.vue.
  const i18nHead = useLocaleHead({ dir: false, lang: false, seo: true })

  // Normalise the self-canonical to a single trailing-slash form so it always
  // matches the URL Netlify actually serves (and the sitemap): `useLocaleHead`
  // omits the slash for the default-locale root.
  const withTrailingSlash = (href: string) =>
    href.endsWith('/') ? href : `${href}/`

  const canonicalLinks = computed(() =>
    i18nHead.value.link.map((link) =>
      link.rel === 'canonical' && link.href
        ? { ...link, href: withTrailingSlash(link.href) }
        : link,
    ),
  )

  const canonical = computed(
    () =>
      canonicalLinks.value.find((link) => link.rel === 'canonical')?.href
      || `${SITE_URL}/`,
  )

  const resolve = (key: string, fallback: string) =>
    te(key) ? String(t(key)) : fallback

  const imagePath = options.image ?? '/og-image.jpg'
  const ogImage = imagePath.startsWith('http')
    ? imagePath
    : `${SITE_URL}${imagePath}`

  useHead(() => {
    const title = resolve(`${section}.metaTitle`, String(t('site.defaultTitle')))
    const description = resolve(
      `${section}.metaDescription`,
      String(t('site.defaultDescription')),
    )
    const keywords = resolve(`${section}.keywords`, '')
    const ogTitle = resolve(`${section}.ogTitle`, title)
    const ogDescription = resolve(`${section}.ogDescription`, description)

    const ogLocale = OG_LOCALES[String(locale.value)] ?? 'en_US'
    const ogLocaleAlternate = Object.values(OG_LOCALES).find(
      (code) => code !== ogLocale,
    )

    const script = options.schema
      ? [
          {
            key: `ld-${section}`,
            type: 'application/ld+json',
            innerHTML: JSON.stringify(options.schema({
              url: canonical.value,
              locale: String(locale.value),
            })),
          },
        ]
      : []

    return {
      title,
      meta: [
        { name: 'description', content: description },
        { name: 'keywords', content: keywords },
        { property: 'og:type', content: options.ogType ?? 'website' },
        { property: 'og:title', content: ogTitle },
        { property: 'og:description', content: ogDescription },
        { property: 'og:url', content: canonical.value },
        { property: 'og:image', content: ogImage },
        { property: 'og:image:alt', content: ogTitle },
        { property: 'og:site_name', content: String(t('site.portfolioName')) },
        { property: 'og:locale', content: ogLocale },
        ...(ogLocaleAlternate
          ? [{ property: 'og:locale:alternate', content: ogLocaleAlternate }]
          : []),
        { name: 'twitter:card', content: 'summary_large_image' },
        { name: 'twitter:title', content: ogTitle },
        { name: 'twitter:description', content: ogDescription },
        { name: 'twitter:image', content: ogImage },
      ],
      // Reciprocal hreflang alternates + self canonical (from `useLocaleHead`).
      link: canonicalLinks.value,
      script,
    }
  })

  return {
    /** Absolute self-referencing canonical URL for the current locale. */
    canonical,
  }
}
